183	/**
184	 * Emit the preamble of a self-contained SMT-LIB script on the
185	 * "liastar-ext-smt" channel: solver options plus a declaration and a
186	 * non-negativity assertion for every star variable in `variables`. The
187	 * queries later emitted on the same channel (see
188	 * `LiaStarUtils::traceDistinctQuery`) then form a replayable soundness check
189	 * of the reduction: every (check-sat) must answer unsat.
190	 */
191	void traceSmtPreamble(Node variables)
192	{
193	  if (!TraceIsOn("liastar-ext-smt"))
194	  {
195	    return;
196	  }
197	  Trace("liastar-ext-smt") << "(set-logic ALL)" << std::endl;
198	  Trace("liastar-ext-smt") << "(set-option :incremental true)" << std::endl;
199	  Trace("liastar-ext-smt") << "(set-option :produce-models true)" << std::endl;
200	  for (Node var : variables)
201	  {
202	    Trace("liastar-ext-smt") << "(declare-const " << var << " Int)"
203	                             << std::endl;
204	  }
205	  for (Node var : variables)
206	  {
207	    Trace("liastar-ext-smt") << "(assert (>= " << var << " 0))" << std::endl;
208	  }
209	}
210	
211	/**
212	 * Emit, on the "liastar-ext-smt" channel, the queries validating the
213	 * membership encoding: one query per disjunct asserting it differs from the
214	 * predicate cell it encodes, and a final query asserting the whole predicate
215	 * (lambda[1]) differs from the disjunction of all membership formulas. All of
216	 * them must be unsat when the trace is replayed.
217	 */
218	void traceMembershipValidation(NodeManager* nm,
219	                               Node lambda,
220	                               const std::vector<std::pair<Node, Node>>& lia)
221	{
222	  for (size_t i = 0; i < lia.size(); i++)
223	  {
224	    LiaStarUtils::traceDistinctQuery(
225	        std::to_string(i), lia[i].first, lia[i].second);
226	  }
227	  std::vector<Node> disjunctions;
228	  std::transform(
229	      lia.begin(), lia.end(), std::back_inserter(disjunctions), [](auto& p) {
230	        return p.second;
231	      });
232	  Node liaFormula;
233	  if (disjunctions.size() == 0)
234	  {
235	    liaFormula = nm->mkConst(false);
236	  }
237	  else if (disjunctions.size() == 1)
238	  {
239	    liaFormula = disjunctions[0];
240	  }
241	  else
242	  {
243	    liaFormula = nm->mkNode(Kind::OR, disjunctions);
244	  }
245	  LiaStarUtils::traceDistinctQuery("lia formula: ", lambda[1], liaFormula);
246	}
