250	LiaStarExtension::LiaStarExtension(Env& env, TheoryArith& containing)
251	    : EnvObj(env),
252	      d_nm(nodeManager()),
253	      d_arith(containing),
254	      d_astate(*containing.getTheoryState()),
255	      d_im(containing.getInferenceManager()),
256	      d_checkCounter(0),
257	      d_extTheoryCb(),
258	      d_extTheory(env, d_extTheoryCb, d_im),
259	      d_hasLiaStarTerms(context(), false)
260	{
261	  d_extTheory.addFunctionKind(Kind::STAR_CONTAINS);
262	  d_true = nodeManager()->mkConst(true);
263	  d_false = nodeManager()->mkConst(false);
264	  d_zero = nodeManager()->mkConstInt(Rational(0));
265	  d_one = nodeManager()->mkConstInt(Rational(1));
266	  // Proofs are produced lazily; allocate the generator only when needed.
267	  if (env.isTheoryProofProducing())
268	  {
269	    d_proofGen.reset(new LiaStarProofGenerator(env, env.getUserContext()));
270	  }
271	}
