275	void LiaStarExtension::preRegisterTerm(TNode n)
276	{
277	  // register terms with extended theory, to find extended terms that can be
278	  // eliminated by context-dependent simplification.
279	  if (d_extTheory.hasFunctionKind(n.getKind()))
280	  {
281	    d_hasLiaStarTerms = true;
282	    d_extTheory.registerTerm(n);
283	  }
