286	void LiaStarExtension::getAssertions(std::vector<Node>& assertions)
287	{
288	  // Collect the STAR_CONTAINS atoms among the arithmetic facts. Both polarities
289	  // are reduced to the positive atom: a negated `(not (star-contains ...))` is
290	  // handled by the same reduction lemma `literal = star` (the surrounding SAT
291	  // solver applies the negation).
292	  Trace("liastar-ext") << "Getting assertions..." << std::endl;
293	  Trace("liastar-ext") << "---------------------" << std::endl;
294	  for (auto it = d_arith.facts_begin(); it != d_arith.facts_end(); ++it)
295	  {
296	    Node lit = (*it).d_assertion;
297	    Trace("liastar-ext") << lit << std::endl;
298	    if (lit.getKind() == Kind::STAR_CONTAINS)
299	    {
300	      // positive polarity of star-contains
301	      assertions.push_back(lit);
302	    }
303	    if (lit.getKind() == Kind::NOT && lit[0].getKind() == Kind::STAR_CONTAINS)
304	    {
305	      // negative polarity of star-contains
306	      assertions.push_back(lit[0]);
307	    }
308	  }
309	  Trace("liastar-ext") << "---------------------" << std::endl;
310	}
311	
312	void LiaStarExtension::checkFullEffort(std::map<Node, Node>& arithModel,
313	                                       const std::set<Node>& termSet)
314	{
315	  // Last-call effort check: for each STAR_CONTAINS assertion emit the necessary
316	  // lemmas and, if the current model does not already satisfy the literal,
317	  // refine via the eager or lazy star reduction.
318	  Trace("liastar-ext") << "interceptModel: do model-based refinement"
319	                       << std::endl;
320	  Trace("liastar-ext") << " model is : " << arithModel << std::endl;
321	  Trace("liastar-ext") << " termSet is: " << termSet << std::endl;
322	  d_checkCounter++;
323	
324	  // get the assertions
325	  std::vector<Node> assertions;
326	  getAssertions(assertions);
327	
328	  Trace("liastar-ext") << "liastar assertions: " << assertions << std::endl;
329	  NodeManager* nm = nodeManager();
330	  for (const auto& literal : assertions)
331	  {
332	    Node lambda = literal[0];
333	    Assert(literal.getKind() == Kind::STAR_CONTAINS);
334	    // vectorPredicate = p[v] (v satisfies p) and nonnegative = (and (>= v_i 0)).
335	    auto [vectorPredicate, nonnegative] =
336	        LiaStarUtils::getVectorPredicate(literal, nm);
337	
338	    // (1) Membership in S* requires v to be in the non-negative orthant.
339	    if (d_proofGen != nullptr)
340	    {
341	      d_proofGen->registerNonnegative(nonnegative, literal);
342	    }
343	    d_im.addPendingLemma(
344	        nonnegative, InferenceId::ARITH_LIA_STAR_NONNEGATIVE, d_proofGen.get());
345	
346	    // (2) Split on whether v itself satisfies p: if so, v is a single-summand
347	    // member of S* and the literal holds directly.
348	    Node split = vectorPredicate.orNode(vectorPredicate.notNode());
349	    if (d_proofGen != nullptr)
350	    {
351	      d_proofGen->registerSplit(split, vectorPredicate);
352	    }
353	    d_im.addPendingLemma(
354	        split, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
355	    d_im.doPendingLemmas();
356	    if (d_im.hasSentLemma())
357	    {
358	      Trace("liastar-ext") << "Sending lemma: " << split << std::endl;
359	      continue;
360	    }
361	    if (options().arith.arithLiaStarModelValue)
362	    {
363	      // Model-value shortcut: if the current arithmetic model already satisfies
364	      // the predicate p[v] (or the last computed star under-approximation),
365	      // then the literal holds in this model and no further refinement is
366	      // needed this round.
367	      std::vector<Node> keys;
368	      std::vector<Node> values;
369	
370	      for (const auto& [key, value] : arithModel)
371	      {
372	        keys.push_back(key);
373	        values.push_back(value);
374	      }
375	
376	      // F: the membership predicate. Additionally consider the last computed
377	      // starLia under-approximation, if any: if the model already satisfies
378	      // F or that under-approximation, the literal already holds and no further
379	      // refinement is needed.
380	      Node f = vectorPredicate;
381	      auto starIt = d_lastStarLia.find(literal);
382	      Node check = starIt != d_lastStarLia.end() ? f.orNode(starIt->second) : f;
383	
384	      Node value = check.substitute(
385	          keys.begin(), keys.end(), values.begin(), values.end());
386	      value = rewrite(value);
387	
388	      Trace("liastar-ext-debug") << "value: " << value << std::endl;
389	
390	      if (value == d_true)
391	      {
392	        Trace("liastar-ext-debug")
393	            << "----------------------------------------" << std::endl;
394	        Trace("liastar-ext-debug")
395	            << literal << " is satisfied in the current model" << std::endl;
396	        Trace("liastar-ext-debug")
397	            << "----------------------------------------" << std::endl;
398	        return;
399	      }
400	    }
401	    // (3) Refine: reduce the star literal to its cone/Hilbert-basis encoding.
402	    if (options().arith.arithLiaStarLazy)
403	    {
404	      lazyCheckStar(literal, lambda);
405	    }
406	    else
407	    {
408	      eagerCheckStar(literal, lambda);
409	    }
410	  }
411	}
412	
413	void LiaStarExtension::eagerCheckStar(Node literal, Node lambda)
414	{
415	  // Eager reduction: compute every cone of p up front and emit the exact
416	  // equivalence `literal = star`. Each literal is reduced at most once.
417	  if (std::find(
418	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
419	      != d_processedStarTerms.end())
420	  {
421	    return;
422	  }
423	  // Normalize p to DNF and render each disjunct as a Normaliz constraint matrix.
424	  std::vector<std::pair<std::vector<std::string>, Node>> pairs =
425	      convertQFLIAToMatrices(lambda);
426	
427	  // Build the cones and the star constraints over all of them.
428	  auto [cones, starConstraints] = getCones(literal, pairs);
429	
430	  if (TraceIsOn("liastar-ext-smt"))
431	  {
432	    // Debug only: build the per-cone membership encoding (v in S, a single
433	    // element) and emit (check-sat) queries asserting it is equivalent to the
434	    // predicate, so a separate solver run can validate the cone decomposition.
435	    // The actual lemma below uses `starConstraints`, not `lia`.
436	    std::vector<std::pair<Node, Node>> lia =
437	        getMembershipDisjuncts(lambda, cones);
438	    Trace("liastar-ext") << "lia constraint: " << std::endl;
439	    traceMembershipValidation(d_nm, lambda, lia);
440	  }
441	  Node star = d_nm->mkNode(Kind::AND, starConstraints);
442	  Trace("liastar-ext") << "starConstraints: " << std::endl
443	                       << toString(starConstraints) << std::endl;
444	  star = rewrite(star);
445	  Node lemma = literal.eqNode(star);
446	  Trace("liastar-ext") << "star lemma: " << lemma << std::endl;
447	  if (d_proofGen != nullptr)
448	  {
449	    d_proofGen->registerContainsReduce(lemma, literal, star);
450	  }
451	  d_im.addPendingLemma(
452	      lemma, InferenceId::ARITH_LIA_STAR_EXISTS, d_proofGen.get());
453	  d_processedStarTerms.push_back(literal);
454	  d_im.doPendingLemmas();
455	}
