563	std::pair<std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>,
564	          std::vector<Node>>
565	LiaStarExtension::getCones(
566	    Node n, const std::vector<std::pair<std::vector<std::string>, Node>>& pairs)
567	{
568	  // Eager path: build a cone for every DNF disjunct (`pairs`) and accumulate
569	  // the star constraints over all of them. Returns (cones, starConstraints):
570	  // the cones (paired with their predicate node) are used to build the
571	  // membership encoding for the debug trace, and starConstraints is the star
572	  // encoding that becomes the reduction lemma.
573	  std::vector<std::pair<Node, Cone<Integer>>> cones;
574	  std::vector<Node> vec(n.begin() + 1, n.end());
575	  size_t dimension = vec.size();
576	  std::vector<std::pair<Vector, std::vector<Vector>>> lambdas;
577	  std::vector<Node> starConstraints;
578	
579	  for (size_t i = 0; i < pairs.size(); i++)
580	  {
581	    const std::pair<std::vector<std::string>, Node>& pair = pairs[i];
582	    Trace("liastar-ext") << "---------------------------" << std::endl;
583	    Trace("liastar-ext") << "Cone for node " << i << std::endl
584	                         << pair.second << std::endl;
585	
586	    Cone<Integer> cone = LiaStarUtils::buildCone(dimension, pair.first);
587	    if (LiaStarUtils::isEmptyCone(cone))
588	    {
589	      // an infeasible disjunct contributes nothing to the star
590	      Trace("liastar-ext") << "empty cone" << std::endl;
591	      continue;
592	    }
593	
594	    for (const auto& generator : getConeGenerators(cone, dimension))
595	    {
596	      Trace("liastar-ext") << toString(generator) << std::endl;
597	      // Build the star encoding of this generator over fresh skolems (the
598	      // constraints are asserted at the top level, not under a quantifier) and
599	      // accumulate its side constraints and its (point, rays) contribution.
600	      std::vector<Node> vars, constraints;
601	      Vector point;
602	      std::vector<Vector> rays;
603	      LiaStarUtils::getGeneratorBody(dimension,
604	                                     generator,
605	                                     cone.getHilbertBasis(),
606	                                     /*star=*/true,
607	                                     /*useSkolems=*/true,
608	                                     d_nm,
609	                                     vars,
610	                                     constraints,
611	                                     point,
612	                                     rays);
613	      starConstraints.insert(
614	          starConstraints.end(), constraints.begin(), constraints.end());
615	      lambdas.push_back({point, rays});
616	    }
617	    cones.push_back({pair.second, cone});
618	  }
619	
620	  // The star vector equals the sum of every cone's contribution.
621	  std::vector<Node> sums = buildSumConstraints(d_nm, d_zero, vec, lambdas);
622	  starConstraints.insert(starConstraints.end(), sums.begin(), sums.end());
623	
624	  return std::make_pair(cones, starConstraints);
625	}
