650	std::vector<Node> LiaStarExtension::getStarConstraints(Node n)
651	{
652	  // Lazy path: return the star constraints over all cones accumulated so far in
653	  // `d_lazyCones[n[0]]`. The per-cone constraints (and their fresh skolems) are
654	  // computed only once per cone and cached in `d_starConstraints`/`d_lambdas`
655	  // (so the skolems are stable across refinement rounds); only the sum
656	  // constraints, which span all cones, are rebuilt on each call.
657	  std::vector<Node> vec(n.begin() + 1, n.end());
658	  size_t dimension = vec.size();
659	
660	  // the cones accumulated so far for this lambda (n[0])
661	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& cones =
662	      d_lazyCones[n[0]];
663	
664	  // The per-cone constraints and lambdas computed in previous calls. We only
665	  // compute new constraints (and fresh skolems) for cones that have not been
666	  // processed yet, and append them here.
667	  std::vector<Node>& starConstraints = d_starConstraints[n[0]];
668	  std::vector<std::pair<Vector, std::vector<Vector>>>& lambdas =
669	      d_lambdas[n[0]];
670	  size_t& processed = d_processedCones[n[0]];
671	
672	  for (; processed < cones.size(); processed++)
673	  {
674	    Cone<Integer>& cone = cones[processed].second;
675	    for (const auto& generator : getConeGenerators(cone, dimension))
676	    {
677	      Trace("liastar-ext") << toString(generator) << std::endl;
678	      // Build the generator's star encoding directly over skolems: the star
679	      // constraints are asserted at the top level (not under a quantifier).
680	      std::vector<Node> vars, constraints;
681	      Vector point;
682	      std::vector<Vector> rays;
683	      LiaStarUtils::getGeneratorBody(dimension,
684	                                     generator,
685	                                     cone.getHilbertBasis(),
686	                                     /*star=*/true,
687	                                     /*useSkolems=*/true,
688	                                     d_nm,
689	                                     vars,
690	                                     constraints,
691	                                     point,
692	                                     rays);
693	      starConstraints.insert(
694	          starConstraints.end(), constraints.begin(), constraints.end());
695	      lambdas.push_back({point, rays});
696	    }
697	  }
698	
699	  // The sum constraints span the lambdas of all cones, so they are rebuilt from
700	  // the accumulated lambdas on each call. Start from the persisted per-cone
701	  // constraints and append the freshly built sum constraints, leaving
702	  // `d_starConstraints` holding only the per-cone constraints.
703	  std::vector<Node> result = starConstraints;
704	  std::vector<Node> sums = buildSumConstraints(d_nm, d_zero, vec, lambdas);
705	  result.insert(result.end(), sums.begin(), sums.end());
706	
707	  return result;
708	}
