710	std::vector<std::pair<Node, Node>> LiaStarExtension::getMembershipDisjuncts(
711	    Node n, std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& cones)
712	{
713	  // Build the *membership* encoding (used only for the liastar-ext-smt debug
714	  // trace): one disjunct per (cone, module generator) stating that the vector
715	  // is a single element `g + sum_k l_k h_k` of that cone, with the multipliers
716	  // existentially bound. The disjunction over all of these is equivalent to
717	  // `v in S` (single membership, not the star). Returns each disjunct paired
718	  // with the predicate node it came from.
719	  Node vec = n[0];
720	  size_t dimension = vec.getNumChildren();
721	  std::vector<std::pair<Node, Node>> disjunctions;
722	
723	  for (auto& pair : cones)
724	  {
725	    Node node = pair.first;
726	    libnormaliz::Cone<Integer>& cone = pair.second;
727	    for (const auto& generator : getConeGenerators(cone, dimension))
728	    {
729	      // Build the generator's membership encoding in terms of bound variables
730	      // and existentially bind them.
731	      std::vector<Node> boundVariables, conjunctions;
732	      Vector point;
733	      std::vector<Vector> rays;
734	      LiaStarUtils::getGeneratorBody(dimension,
735	                                     generator,
736	                                     cone.getHilbertBasis(),
737	                                     /*star=*/false,
738	                                     /*useSkolems=*/false,
739	                                     d_nm,
740	                                     boundVariables,
741	                                     conjunctions,
742	                                     point,
743	                                     rays);
744	
745	      // the vector equals this single element: vec[i] = point[i] + sum rays
746	      Vector sums(dimension, d_zero);
747	      for (size_t i = 0; i < dimension; i++)
748	      {
749	        sums[i] = rewrite(d_nm->mkNode(Kind::ADD, sums[i], point[i]));
750	        for (const auto& ray : rays)
751	        {
752	          sums[i] = rewrite(d_nm->mkNode(Kind::ADD, sums[i], ray[i]));
753	        }
754	      }
755	
756	      for (size_t i = 0; i < dimension; i++)
757	      {
758	        conjunctions.push_back(vec[i].eqNode(sums[i]));
759	      }
760	      Node conjunction = d_nm->mkNode(Kind::AND, conjunctions);
761	      if (boundVariables.size() > 0)
762	      {
763	        Node variables = d_nm->mkNode(Kind::BOUND_VAR_LIST, boundVariables);
764	        conjunction = d_nm->mkNode(Kind::EXISTS, variables, conjunction);
765	      }
766	      disjunctions.push_back({node, conjunction});
767	    }
768	  }
769	
770	  return disjunctions;
771	}
