773	const std::vector<std::pair<std::vector<std::string>, Node>>
774	LiaStarExtension::convertQFLIAToMatrices(Node n)
775	{
776	  // Normalize the lambda body `p` to DNF and render each disjunct as a Normaliz
777	  // constraint matrix (one cone per disjunct). `n` is the lambda
778	  // (lambda ((x_1 Int) ... (x_n Int)) p).
779	  Assert(n.getKind() == Kind::LAMBDA);
780	
781	  Node variables = n[0];
782	  Node predicate = n[1];
783	  Trace("liastar-ext") << "convertQFLIAToMatrices::n: " << n << std::endl;
784	  Trace("liastar-ext") << "variables: " << variables << std::endl;
785	
786	  Trace("liastar-ext") << "predicate: " << predicate << std::endl;
787	
788	  traceSmtPreamble(variables);
789	
790	  Node dnf = LiaStarUtils::toDNF(predicate, &d_env);
791	
792	  Trace("liastar-ext") << "predicate in dnf: " << dnf << std::endl;
793	  Trace("liastar-ext") << "lia constraint: " << std::endl;
794	
795	  std::vector<std::pair<std::vector<std::string>, Node>> pairs =
796	      LiaStarUtils::getMatrices(variables, dnf);
797	  return pairs;
798	}
