169	void ContextManager::doPendingPops()
170	{
171	  Trace("smt") << "ContextManager::doPendingPops()" << std::endl;
172	  Assert(d_pendingPops == 0 || options().base.incrementalSolving);
173	  // check to see if a postsolve() is pending
174	  if (d_needPostsolve)
175	  {
176	    d_smt->notifyPostSolve();
177	    d_needPostsolve = false;
178	  }
179	  while (d_pendingPops > 0)
180	  {
181	    // the context pop is done inside of the SAT solver
182	    d_smt->notifyPopPre();
183	    // pop the context
184	    userContext()->pop();
185	    --d_pendingPops;
186	    // no need for pop post (for now)
187	  }
188	}
