951	void SolverEngine::assertFormulaInternal(const Node& formula)
952	{
953	  // as an optimization we do not check whether formula is well-formed here, and
954	  // defer this check for certain cases within the assertions module.
955	  Trace("smt") << "SolverEngine::assertFormula(" << formula << ")" << endl;
956	  Node f = formula;
957	  // If we are proof producing and don't permit subtypes, we rewrite now.
958	  // Otherwise we will have an assumption with mixed arithmetic which is
959	  // not permitted in proofs that cannot be eliminated, and will require a
960	  // trust step.
961	  // We don't care if we are an internal subsolver, as this rewriting only
962	  // impacts having exportable, complete proofs, which is not an issue for
963	  // internal subsolvers.
964	  if (d_env->isProofProducing() && !d_isInternalSubsolver)
965	  {
966	    if (options().proof.proofElimSubtypes)
967	    {
968	      SubtypeElimNodeConverter senc(d_env->getNodeManager());
969	      f = senc.convert(formula);
970	      // note we could throw a warning here if formula and f are different,
971	      // but currently don't.
972	    }
973	  }
974	  d_smtSolver->getAssertions().assertFormula(f);
975	}
