865	  // Render a DNF predicate into one Normaliz matrix per disjunct (cone). A
866	  // disjunction yields one matrix per child; any other shape (atom,
867	  // conjunction, boolean constant) is a single disjunct handled by `getMatrix`.
868	  Assert(n.getType().isBoolean()) << "n: " << n << std::endl;
869	  if (n.getKind() == Kind::OR)
870	  {
871	    std::vector<std::pair<std::vector<std::string>, Node>> pairs;
872	    for (size_t i = 0; i < n.getNumChildren(); i++)
873	    {
874	      Trace("liastar-ext") << "Disjunction " << i << ": " << n[i] << std::endl;
875	      pairs.push_back(getMatrix(variables, n[i]));
876	    }
877	    return pairs;
878	  }
879	  return {getMatrix(variables, n)};
880	}
